import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { updateBankInfo, fetchCompany } from "../Features/CompanySlice";
import "../Styles/UserProfile.css"; // Using same CSS as user profile

const CompanyProfile = () => {
  const dispatch = useDispatch();
  // Logout function to clear user session and navigate to login
  const handleLogout = async () => {
    // Remove all saved session data
    localStorage.removeItem("role");
    localStorage.removeItem("loggedUser");
    localStorage.removeItem("token"); // optional if you used token
    localStorage.removeItem("applications");

    // Also reset Redux state
    dispatch(logout());

    // Small delay before navigation
    await new Promise((resolve) => setTimeout(resolve, 100));
    navigate("/login");
  };

  const { company, isLoading, isSuccess } = useSelector(
    (state) => state.company
  );

  // States for modal and payment form
  const [showEditCompany, setShowEditCompany] = useState(false);
  const [showEditPayment, setShowEditPayment] = useState(false);
  const [payment, setPayment] = useState({
    accountHolder: "",
    bankName: "",
    accountNumber: "",
    iban: "",
  });

  // Fetch company data when the page loads
  useEffect(() => {
    if (company?.email) {
      dispatch(fetchCompany(company.email));
    }
  }, [dispatch, company?.email]);

  // Save or update bank details in MongoDB
  const handleSavePayment = (e) => {
    e.preventDefault();
    if (!company?.email) {
      alert("Please login first!");
      return;
    }
    dispatch(updateBankInfo({ email: company.email, bankData: payment }))
      .unwrap()
      .then(() => {
        alert("Bank details saved successfully!");
        setShowEditPayment(false);
      })
      .catch(() => alert("Failed to save bank details"));
  };

  // Clear bank info locally (not from database)
  const handleDeletePayment = () => {
    setPayment({
      accountHolder: "",
      bankName: "",
      accountNumber: "",
      iban: "",
    });
    alert("Bank details cleared locally.");
  };

  // Show while loading
  if (isLoading)
    return <p style={{ textAlign: "center" }}>Loading company data...</p>;

  // If no data found
  if (!company || !company.companyName)
    return <p style={{ textAlign: "center" }}>No company data found.</p>;

  return (
    <div className="profile-page">
      {/* Company basic information section */}
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-icon">🏢</div>
          <div>
            <h2 className="profile-name">{company.companyName}</h2>
            <p className="profile-email">{company.email}</p>
            <p className="profile-detail">
              {company.industry} • {company.location}
            </p>
            <p className="profile-detail">
              Founded: {company.foundedDate || "N/A"}
            </p>
          </div>
        </div>
        <button className="update-btn" onClick={() => setShowEditCompany(true)}>
          Update Info
        </button>
      </div>

      {/* Company bank information section */}
      <div className="payment-box">
        <h3>Bank Details</h3>

        {!company.bankInfo ? (
          <div>
            <p>No bank details added yet.</p>
            <button
              className="add-btn"
              onClick={() => setShowEditPayment(true)}
            >
              Add Bank Info
            </button>
          </div>
        ) : (
          <div className="payment-info">
            <p>Account Holder: {company.bankInfo?.accountHolder}</p>
            <p>Bank Name: {company.bankInfo?.bankName}</p>
            <p>Account Number: {company.bankInfo?.accountNumber}</p>
            <p>IBAN: {company.bankInfo?.iban}</p>

            <div className="payment-actions">
              <button
                className="update-btn small"
                onClick={() => setShowEditPayment(true)}
              >
                Edit Bank
              </button>
              <button
                className="delete-btn small"
                onClick={handleDeletePayment}
              >
                Delete
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Modal for adding/editing bank info */}
      {showEditPayment && (
        <div className="modal-overlay">
          <div className="modal-content small">
            <h3>Add / Edit Bank Info</h3>
            <form onSubmit={handleSavePayment}>
              <label>Account Holder</label>
              <input
                type="text"
                placeholder="e.g. Dhofar Advertising Co."
                value={payment.accountHolder}
                onChange={(e) =>
                  setPayment({ ...payment, accountHolder: e.target.value })
                }
                required
              />

              <label>Bank Name</label>
              <select
                value={payment.bankName}
                onChange={(e) =>
                  setPayment({ ...payment, bankName: e.target.value })
                }
                required
              >
                <option value="">Select your bank</option>
                <option>Bank Muscat</option>
                <option>Bank Dhofar</option>
                <option>National Bank of Oman</option>
                <option>Oman Arab Bank</option>
                <option>Sohar International</option>
              </select>

              <label>IBAN</label>
              <input
                type="text"
                placeholder="e.g. OM84 0000 0000 1234 5678 9012"
                value={payment.iban}
                onChange={(e) =>
                  setPayment({ ...payment, iban: e.target.value })
                }
              />

              <label>Account Number</label>
              <input
                type="text"
                placeholder="e.g. 123456789012"
                value={payment.accountNumber}
                onChange={(e) =>
                  setPayment({ ...payment, accountNumber: e.target.value })
                }
              />

              <div className="modal-btns">
                <button type="submit" className="save-btn">
                  Save
                </button>
                <button
                  type="button"
                  className="cancel-btn"
                  onClick={() => setShowEditPayment(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanyProfile;
